// Кейс: .qa/tests/monitoring/MON-035.md (ручной звонок — MON-034) · план: .qa/e2e-app/specs/app.md (1.55)
// iPhone — камера (Appium), Pixel — второй телефон (adb). Имитация полноэкранного звонка: iPhone уходит в фон на BANCI_CALL_BG_SEC (по умолчанию 45 с).
// На Pixel «בית»: заголовок «הבריכה לא במעקב» весь фон и ни разу «הניטור פעיל»; после возврата — «הניטור פעיל» снова. Сам звонок, push и цвет — вручную.
// ЗАПУСКАЕТ МОНИТОРИНГ (сеанс в «היסטוריה») — только с BANCI_MONITORING=1 + BANCI_ANDROID_SERIAL.
import { by, assert } from '../../lib/appium.mjs';
import { startMonitoring, endMonitoring, waitTimer, collectEvents, countOf, fmtEvents, EV } from '../../lib/monitoring.mjs';
import { requireSecondPhone, pixelHome, HEADER_ACTIVE, HEADER_NOT_TRACKED } from '../../lib/second-phone.mjs';

export const name = 'Камера в фоне (имитация звонка): на втором телефоне «הבריכה לא במעקב», не «הניטור פעיל»; после возврата «הניטור פעיל», одна пара ירדה לרקע/חזר לפעול #8b8e4f @iphone @app @data';

export default async function (app) {
  const pixel = await requireSecondPhone();
  const bgSec = Number(process.env.BANCI_CALL_BG_SEC || 45);

  // 1. Pixel на «בית»; iPhone — мониторинг; на Pixel «הניטור פעיל».
  await pixelHome(pixel);
  await startMonitoring(app);
  await waitTimer(app, 5);
  await pixel.waitFor(HEADER_ACTIVE, { exact: true, timeout: 30000, what: 'Pixel: заголовок «הניטור פעיל», пока мониторинг идёт' });

  // 2. iPhone уходит в фон (как при звонке во весь экран); параллельно опрашиваем Pixel.
  const background = app.exec('mobile: backgroundApp', { seconds: bgSec });
  let done = false;
  background.then(() => { done = true; }, () => { done = true; });
  await pixel.waitFor(HEADER_NOT_TRACKED, { exact: true, timeout: 15000, what: 'Pixel: заголовок «הבריכה לא במעקב» ≤ 15 с после ухода камеры в фон' });
  let polls = 0;
  while (!done) {
    const active = await pixel.findAll(HEADER_ACTIVE, { exact: true });
    assert(!active.length, 'пока камера в фоне, на Pixel нет заголовка «הניטור פעיל» (опрос #' + (polls + 1) + ')');
    polls++;
  }
  await background;
  assert(polls >= 1, 'во время фона был хотя бы один опрос Pixel');

  // 3. Возврат: если лист «הניטור הופסק» — «המשך ניטור»; затем «תקין».
  await app.activate();
  await app.waitFor(`(${by.exact('המשך ניטור')}) OR (${by.exact('תקין')})`, { timeout: 30000, what: 'лист «הניטור הופסק» или статус «תקין» после возврата' });
  if (await app.exists(by.exact('המשך ניטור'))) await (await app.waitFor(by.exact('המשך ניטור'), { what: '«המשך ניטור»' })).click();
  await app.waitFor(by.exact('תקין'), { timeout: 30000, what: 'статус «תקין» после возврата' });

  // 4. Pixel: заголовок вернулся.
  await pixel.waitFor(HEADER_ACTIVE, { exact: true, timeout: 30000, what: 'Pixel: заголовок снова «הניטור פעיל» после возврата камеры' });
  assert(!(await pixel.findAll(HEADER_NOT_TRACKED, { exact: true })).length, 'на Pixel нет заголовка «הבריכה לא במעקב» после возврата');

  // 5. Лента: одна пара на фон.
  const events = await collectEvents(app);
  assert(countOf(events, EV.BACKGROUND) === 1, `ровно одно «${EV.BACKGROUND}» (${fmtEvents(events)})`);
  assert(countOf(events, EV.RESUMED) === 1, `ровно одно «${EV.RESUMED}» (${fmtEvents(events)})`);
  await endMonitoring(app);
}
